alter table public.posts add column if not exists quoted_post_id uuid null references public.posts(id) on delete set null;
create index if not exists posts_quoted_post_id_idx on public.posts(quoted_post_id);
create table if not exists public.post_polls (id uuid primary key default gen_random_uuid(),post_id uuid not null unique references public.posts(id) on delete cascade,ends_at timestamptz null,created_at timestamptz not null default now());
create table if not exists public.poll_options (id uuid primary key default gen_random_uuid(),poll_id uuid not null references public.post_polls(id) on delete cascade,option_text varchar(80) not null check(length(btrim(option_text)) between 1 and 80),position smallint not null check(position between 0 and 3),unique(poll_id,position),unique(id,poll_id));
create table if not exists public.poll_votes (poll_id uuid not null references public.post_polls(id) on delete cascade,option_id uuid not null,user_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(poll_id,user_id),foreign key(option_id,poll_id) references public.poll_options(id,poll_id) on delete cascade);
create index if not exists poll_votes_poll_option_idx on public.poll_votes(poll_id,option_id);
alter table public.post_polls enable row level security;alter table public.poll_options enable row level security;alter table public.poll_votes enable row level security;
drop policy if exists "Polls are public" on public.post_polls;create policy "Polls are public" on public.post_polls for select to anon,authenticated using(true);
drop policy if exists "Post authors create their polls" on public.post_polls;create policy "Post authors create their polls" on public.post_polls for insert to authenticated with check(exists(select 1 from public.posts p where p.id=post_id and p.author_id=(select auth.uid())));
drop policy if exists "Poll authors update their polls" on public.post_polls;create policy "Poll authors update their polls" on public.post_polls for update to authenticated using(exists(select 1 from public.posts p where p.id=post_id and p.author_id=(select auth.uid()))) with check(exists(select 1 from public.posts p where p.id=post_id and p.author_id=(select auth.uid())));
drop policy if exists "Poll options are public" on public.poll_options;create policy "Poll options are public" on public.poll_options for select to anon,authenticated using(true);
drop policy if exists "Post authors add poll options" on public.poll_options;create policy "Post authors add poll options" on public.poll_options for insert to authenticated with check(exists(select 1 from public.post_polls pp join public.posts p on p.id=pp.post_id where pp.id=poll_id and p.author_id=(select auth.uid())));
drop policy if exists "Poll votes are public" on public.poll_votes;create policy "Poll votes are public" on public.poll_votes for select to anon,authenticated using(true);
drop policy if exists "Citizens cast their own votes" on public.poll_votes;create policy "Citizens cast their own votes" on public.poll_votes for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.post_polls pp where pp.id=poll_id and (pp.ends_at is null or pp.ends_at>now())));
drop policy if exists "Citizens change their own votes" on public.poll_votes;create policy "Citizens change their own votes" on public.poll_votes for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()) and exists(select 1 from public.post_polls pp where pp.id=poll_id and (pp.ends_at is null or pp.ends_at>now())));
drop policy if exists "Citizens remove their own votes" on public.poll_votes;create policy "Citizens remove their own votes" on public.poll_votes for delete to authenticated using(user_id=(select auth.uid()));
revoke all on public.post_polls,public.poll_options,public.poll_votes from anon,authenticated;grant select on public.post_polls,public.poll_options,public.poll_votes to anon,authenticated;grant insert,update on public.post_polls to authenticated;grant insert on public.poll_options to authenticated;grant insert,update,delete on public.poll_votes to authenticated;
